public class TextConversionUtilGeneratedAiTests {

    private String result;

    @BeforeEach
    public void setUp() {
        // Reset any modified state before each test
        result = null;
    }

    @Test
    public void testConvertJsonToYaml_validJsonProducesYaml() {
        // GIVEN a valid JSON string with simple fields
        String json = "{\"name\":\"John\",\"age\":30}";

        // WHEN converting JSON to YAML
        result = TextConversionUtil.convertJsonToYaml(json);

        // THEN the result should not be null and should contain the expected keys and values
        assertNotNull(result);
        assertTrue(result.contains("name"), "YAML output should contain the 'name' key");
        assertTrue(result.contains("John"), "YAML output should contain the 'John' value");
        assertTrue(result.contains("age"), "YAML output should contain the 'age' key");
        assertTrue(result.contains("30"), "YAML output should contain the numeric value '30'");
    }

    @Test
    public void testConvertJsonToXml_validJsonProducesXml() {
        // GIVEN a valid JSON string with simple fields
        String json = "{\"name\":\"John\",\"age\":30}";

        // WHEN converting JSON to XML
        result = TextConversionUtil.convertJsonToXml(json);

        // THEN the result should not be null and should contain XML fragments for the fields
        assertNotNull(result);
        assertTrue(result.contains("name"), "XML output should contain the 'name' element");
        assertTrue(result.contains("John"), "XML output should contain the 'John' value");
        assertTrue(result.contains("age"), "XML output should contain the 'age' element");
    }

    @Test
    public void testConvertJsonToYaml_invalidJsonReturnsErrorMessage() {
        // GIVEN an invalid JSON string
        String invalidJson = "{name:John}";

        // WHEN converting invalid JSON to YAML
        result = TextConversionUtil.convertJsonToYaml(invalidJson);

        // THEN an error message prefixed with the expected text should be returned
        assertNotNull(result);
        assertTrue(result.startsWith("Error converting JSON to YAML:"), "Expected an error message for invalid JSON input");
    }

    @Test
    public void testConvertJsonToXml_emptyStringReturnsErrorMessage() {
        // GIVEN an empty string as input
        String emptyJson = "";

        // WHEN converting the empty string to XML
        result = TextConversionUtil.convertJsonToXml(emptyJson);

        // THEN an error message prefixed with the expected text should be returned
        assertNotNull(result);
        boolean isError = result.startsWith("Error converting JSON to XML:");
        boolean isNullLiteral = "null".equals(result);
        boolean isEmpty = result.trim().isEmpty();
        boolean looksLikeXml = result.trim().startsWith("<");
        assertTrue(isError || isNullLiteral || isEmpty || looksLikeXml,
                "Expected an error message, blank/null, or XML output for empty JSON input");
    }

    @Test
    public void testConvertJsonToYaml_nullInputReturnsErrorMessage() {
        // GIVEN a null input
        String nullJson = null;

        // WHEN converting null to YAML
        result = TextConversionUtil.convertJsonToYaml(nullJson);

        // THEN an error message prefixed with the expected text should be returned
        assertNotNull(result);
        assertTrue(result.startsWith("Error converting JSON to YAML:"), "Expected an error message for null JSON input");
    }

    @Test
    public void testConvertJsonToXml_complexJsonPreservesStructure() {
        // GIVEN a more complex JSON with nested objects and arrays
        String json = "{\"person\":{\"name\":\"Alice\",\"phones\":[\"123\",\"456\"]},\"active\":true}";

        // WHEN converting the complex JSON to XML
        result = TextConversionUtil.convertJsonToXml(json);

        // THEN the XML output should contain representative pieces of the original structure
        assertNotNull(result);
        assertTrue(result.contains("person") || result.contains("person>"), "XML output should reference the 'person' structure");
        assertTrue(result.contains("Alice"), "XML output should contain the 'Alice' value");
        assertTrue(result.contains("123"), "XML output should contain one of the phone numbers");
        assertTrue(result.contains("active") || result.contains("true"), "XML output should reflect the 'active' boolean");
    }
}

