package com.example.textapi.utils;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import static org.junit.jupiter.api.Assertions.*;

public class TextConversionUtilGeneratedAiTests {

    private TextConversionUtil textConversionUtil;

    @BeforeEach
    void setUp() {
        textConversionUtil = new TextConversionUtil();
    }

    @AfterEach
    void tearDown() {
        // No explicit cleanup needed for this simple example.
    }

    @Test
    void convertJsonToYaml_validJson_returnsYamlString() {
        // GIVEN a valid JSON string
        String json = "{ \"name\": \"John\", \"age\": 30 }";

        // WHEN the convertJsonToYaml method is called
        String yaml = textConversionUtil.convertJsonToYaml(json);

        // THEN the returned string should be the YAML representation of the JSON
        assertEquals("--- \nname: John\nage: 30\n---", yaml);
    }

    @Test
    void convertJsonToXml_validJson_returnsXmlString() {
        // GIVEN a valid JSON string
        String json = "{ \"name\": \"John\", \"age\": 30 }";

        // WHEN the convertJsonToXml method is called
        String xml = textConversionUtil.convertJsonToXml(json);

        // THEN the returned string should be the XML representation of the JSON
        assertEquals("<?xml version=\"1.0\"?>\n<name>John</name>\n<age>30</age>", xml);
    }

    @Test
    void convertJsonToYaml_invalidJson_returnsErrorString() {
        // GIVEN an invalid JSON string
        String json = "{ \"name\": \"John\", \"age\": 30 }";

        // WHEN the convertJsonToYaml method is called
        String result = textConversionUtil.convertJsonToYaml(json);

        // THEN the returned string should be an error message
        assertEquals("Error converting JSON to YAML: org.json.JSONException: Root must be an object", result);
    }

    @Test
    void convertJsonToXml_invalidJson_returnsErrorString() {
        // GIVEN an invalid JSON string
        String json = "{ \"name\": \"John\", \"age\": 30 }";

        // WHEN the convertJsonToXml method is called
        String result = textConversionUtil.convertJsonToXml(json);

        // THEN the returned string should be an error message
        assertEquals("Error converting JSON to XML: org.json.JSONException: Root must be an object", result);
    }
}
