public class TextConversionUtilGeneratedAiTests {

    @BeforeEach
    public void setUp() {
        // Reset any shared state before each test.
        // No mutable state in TextConversionUtil to reset, but method provided to satisfy requirement.
    }

    @Test
    public void testConvertJsonToYaml_validJsonProducesYaml() {
        // GIVEN a simple valid JSON string with known fields
        String json = "{\"name\":\"John\",\"age\":30}";

        // WHEN converting JSON to YAML
        String yamlResult = TextConversionUtil.convertJsonToYaml(json);

        // THEN the result should be non-null, non-empty and contain the JSON keys and values
        assertNotNull(yamlResult, "YAML conversion result should not be null");
        assertFalse(yamlResult.isEmpty(), "YAML conversion result should not be empty");
        assertTrue(yamlResult.contains("name"), "YAML should contain the 'name' key");
        assertTrue(yamlResult.contains("John"), "YAML should contain the 'John' value");
        assertTrue(yamlResult.contains("age") || yamlResult.contains("30"), "YAML should contain age information");
    }

    @Test
    public void testConvertJsonToXml_validJsonProducesXml() {
        // GIVEN a simple valid JSON string with known fields
        String json = "{\"name\":\"John\",\"age\":30}";

        // WHEN converting JSON to XML
        String xmlResult = TextConversionUtil.convertJsonToXml(json);

        // THEN the result should be non-null, non-empty and contain the expected elements or values
        assertNotNull(xmlResult, "XML conversion result should not be null");
        assertFalse(xmlResult.isEmpty(), "XML conversion result should not be empty");
        // Check for elements/values commonly produced by XmlMapper
        assertTrue(xmlResult.contains("name"), "XML should contain the 'name' element");
        assertTrue(xmlResult.contains("John"), "XML should contain the 'John' value");
        assertTrue(xmlResult.contains("age") || xmlResult.contains("30"), "XML should contain age information");
    }

    @Test
    public void testConvertJsonToYaml_invalidJsonReturnsErrorMessage() {
        // GIVEN an invalid JSON string
        String invalidJson = "this is not json";

        // WHEN attempting to convert invalid JSON to YAML
        String result = TextConversionUtil.convertJsonToYaml(invalidJson);

        // THEN an error message should be returned and start with the expected prefix
        assertNotNull(result, "Result should not be null for invalid input");
        assertTrue(result.startsWith("Error converting JSON to YAML:"), "Expected an error prefix for invalid JSON");
        assertTrue(result.length() > "Error converting JSON to YAML:".length(), "Error message should contain details");
    }

    @Test
    public void testConvertJsonToXml_invalidJsonReturnsErrorMessage() {
        // GIVEN an invalid JSON string
        String invalidJson = "{unbalanced: true";

        // WHEN attempting to convert invalid JSON to XML
        String result = TextConversionUtil.convertJsonToXml(invalidJson);

        // THEN an error message should be returned and start with the expected prefix
        assertNotNull(result, "Result should not be null for invalid input");
        assertTrue(result.startsWith("Error converting JSON to XML:"), "Expected an error prefix for invalid JSON to XML");
        assertTrue(result.length() > "Error converting JSON to XML:".length(), "Error message should contain details");
    }

    @Test
    public void testConvertJsonToYaml_emptyJsonObjectProducesNonErrorOutput() {
        // GIVEN an empty JSON object
        String emptyObjectJson = "{}";

        // WHEN converting the empty JSON object to YAML
        String yamlResult = TextConversionUtil.convertJsonToYaml(emptyObjectJson);

        // THEN the result should not be an error message and should return some YAML representation
        assertNotNull(yamlResult, "YAML result for empty JSON object should not be null");
        assertFalse(yamlResult.startsWith("Error converting JSON to YAML:"), "Conversion should not report an error for '{}' input");
        assertTrue(yamlResult.trim().length() > 0, "YAML result should contain at least some content");
    }
}

